INSERT INTO "moodle_courses" ("id", "run_id", "moodle_course_id", "category_id", "title", "normalized_title", "course_url", "enrol_url", "summary_text", "summary_html", "teachers_json", "detected_codes_json", "detected_terms_json", "self_enrol_available", "guest_access", "limit_mentioned", "limit_text", "participant_limit_value", "raw_json") VALUES (6, 1, '1468', '235', 'Enterprise Computing - Anwendungen (INF4323)', 'enterprise computing - anwendungen (inf4323)', 'https://moodle.zdv.uni-tuebingen.de/course/view.php?id=1468', 'https://moodle.zdv.uni-tuebingen.de/enrol/index.php?id=1468', 'Großrechner sind zentraler Bestandteil in zahlreichen großen Unternehmen. Diese Vorlesung beschreibt die modernen Software Anwendungen, die auf solchen Rechnern angewendet werden. Neben klassischen Technologien wie Transaktionsverarbeitung und Datenbanken werden Einsatzgebiete in den Bereichen Cloud Computing, KI, Big Data, Cybersecurity und Quantum Computing beschrieben. Um die neuesten Erkenntnisse dieser Themen zu zeigen treten Gastdozenten aus der IT Entwicklung auf. Einige Themen werden in englischer Sprache gehalten.', '<div class="no-overflow"><p>Großrechner sind zentraler Bestandteil in zahlreichen großen Unternehmen. Diese Vorlesung beschreibt die modernen Software Anwendungen, die auf solchen Rechnern angewendet werden. Neben klassischen Technologien wie Transaktionsverarbeitung und Datenbanken werden Einsatzgebiete in den Bereichen Cloud Computing, KI, Big Data, Cybersecurity und Quantum Computing beschrieben. Um die neuesten Erkenntnisse dieser Themen zu zeigen treten Gastdozenten aus der IT Entwicklung auf. Einige Themen werden in englischer Sprache gehalten. </p></div>', '[{"display_name": "Jörg Gamerdinger", "profile_url": "https://moodle.zdv.uni-tuebingen.de/user/profile.php?id=30125", "moodle_user_id": "30125"}, {"display_name": "Rolf Schmidt", "profile_url": "https://moodle.zdv.uni-tuebingen.de/user/profile.php?id=220", "moodle_user_id": "220"}, {"display_name": "Julius Wührer", "profile_url": "https://moodle.zdv.uni-tuebingen.de/user/profile.php?id=54520", "moodle_user_id": "54520"}]', '["INF4323"]', '[]', 1, 0, 0, NULL, NULL, '{"coursebox_classes": ["coursebox", "clearfix", "odd"], "data_type": "1", "course_page_url": "https://moodle.zdv.uni-tuebingen.de/enrol/index.php?id=1468", "enrolment_labels": ["Selbsteinschreibung (Studierende*r)"]}');
INSERT INTO "moodle_courses" ("id", "run_id", "moodle_course_id", "category_id", "title", "normalized_title", "course_url", "enrol_url", "summary_text", "summary_html", "teachers_json", "detected_codes_json", "detected_terms_json", "self_enrol_available", "guest_access", "limit_mentioned", "limit_text", "participant_limit_value", "raw_json") VALUES (7, 1, '1471', '235', 'INFO-4354 Public Cloud Computing (SoSe26)', 'info-4354 public cloud computing (sose26)', 'https://moodle.zdv.uni-tuebingen.de/course/view.php?id=1471', 'https://moodle.zdv.uni-tuebingen.de/enrol/index.php?id=1471', 'Die Vorlesung vermittelt fortgeschrittene Kenntnisse in Containertechnologie, Software-as-a-Service (SaaS) und Function-as-a-Service (FaaS). Es werden theoretische Asätze zu Cloud-Architekturen, Cloud Computing Patterns und Automatisierung besprochen. Klassische Anwendungsfälle wie Serverless Computing, Internet of Things (IoT), Edge Computing, Business Intelligence (BI) und Machine Learning (ML) werden aufgezeigt. Der Übungsbetrieb besteht aus umfangreichen, praktischen Aufgaben und adressiert insbesondere operativen Betrieb, wirtschaftliche Effizienz und Sicherheit.', '<div class="no-overflow"><p>Die Vorlesung vermittelt fortgeschrittene Kenntnisse in Containertechnologie, Software-as-a-Service (SaaS) und Function-as-a-Service (FaaS). Es werden theoretische Asätze zu Cloud-Architekturen, Cloud Computing Patterns und Automatisierung besprochen. Klassische Anwendungsfälle wie Serverless Computing, Internet of Things (IoT), Edge Computing, Business Intelligence (BI) und Machine Learning (ML) werden aufgezeigt. Der Übungsbetrieb besteht aus umfangreichen, praktischen Aufgaben und adressiert insbesondere operativen<br/>Betrieb, wirtschaftliche Effizienz und Sicherheit.</p></div>', '[{"display_name": "Tobias Hüttner", "profile_url": "https://moodle.zdv.uni-tuebingen.de/user/profile.php?id=27613", "moodle_user_id": "27613"}, {"display_name": "Michael Menth", "profile_url": "https://moodle.zdv.uni-tuebingen.de/user/profile.php?id=160", "moodle_user_id": "160"}, {"display_name": "Etienne Laurent Zink", "profile_url": "https://moodle.zdv.uni-tuebingen.de/user/profile.php?id=63", "moodle_user_id": "63"}]', '["INFO4354"]', '["SoSe26"]', 1, 0, 0, NULL, NULL, '{"coursebox_classes": ["coursebox", "clearfix", "odd"], "data_type": "1", "course_page_url": "https://moodle.zdv.uni-tuebingen.de/enrol/index.php?id=1471", "enrolment_labels": ["Selbsteinschreibung (Studierende*r)"]}');
INSERT INTO "moodle_courses" ("id", "run_id", "moodle_course_id", "category_id", "title", "normalized_title", "course_url", "enrol_url", "summary_text", "summary_html", "teachers_json", "detected_codes_json", "detected_terms_json", "self_enrol_available", "guest_access", "limit_mentioned", "limit_text", "participant_limit_value", "raw_json") VALUES (8, 1, '1473', '235', 'Algorithmische Geometrie', 'algorithmische geometrie', 'https://moodle.zdv.uni-tuebingen.de/course/view.php?id=1473', 'https://moodle.zdv.uni-tuebingen.de/enrol/index.php?id=1473', 'Vorlesung Algorithmische Geometrie (Bachelor). Wir beschäftigen uns mit grundlegenden Themen aus der Algorithmischen Geometrie wie konvexer Hülle, Voronoi Diagramm, Triangulierung, kürzeste Wege in Polygonen, ....', '<div class="no-overflow"><p>Vorlesung <em>Algorithmische Geometrie </em>(Bachelor).</p> <p>Wir beschäftigen uns mit grundlegenden Themen aus der Algorithmischen Geometrie wie konvexer Hülle, Voronoi Diagramm, Triangulierung, kürzeste Wege in Polygonen, ....</p></div>', '[{"display_name": "Lena Marie Schlipf", "profile_url": "https://moodle.zdv.uni-tuebingen.de/user/profile.php?id=197", "moodle_user_id": "197"}]', '[]', '[]', 1, 0, 0, NULL, NULL, '{"coursebox_classes": ["coursebox", "clearfix", "even"], "data_type": "1", "course_page_url": "https://moodle.zdv.uni-tuebingen.de/enrol/index.php?id=1473", "enrolment_labels": ["Selbsteinschreibung (Studierende*r)"]}');
INSERT INTO "moodle_courses" ("id", "run_id", "moodle_course_id", "category_id", "title", "normalized_title", "course_url", "enrol_url", "summary_text", "summary_html", "teachers_json", "detected_codes_json", "detected_terms_json", "self_enrol_available", "guest_access", "limit_mentioned", "limit_text", "participant_limit_value", "raw_json") VALUES (9, 1, '1474', '235', 'Spezielle Themen der Algorithmik', 'spezielle themen der algorithmik', 'https://moodle.zdv.uni-tuebingen.de/course/view.php?id=1474', 'https://moodle.zdv.uni-tuebingen.de/enrol/index.php?id=1474', 'Vorlesung Spezielle Themen der Algorithmik (Master)', '<div class="no-overflow"><p>Vorlesung <em>Spezielle Themen der Algorithmik </em>(Master)</p></div>', '[{"display_name": "Lena Marie Schlipf", "profile_url": "https://moodle.zdv.uni-tuebingen.de/user/profile.php?id=197", "moodle_user_id": "197"}]', '[]', '[]', 1, 0, 0, NULL, NULL, '{"coursebox_classes": ["coursebox", "clearfix", "even"], "data_type": "1", "course_page_url": "https://moodle.zdv.uni-tuebingen.de/enrol/index.php?id=1474", "enrolment_labels": ["Selbsteinschreibung (Studierende*r)"]}');
INSERT INTO "moodle_courses" ("id", "run_id", "moodle_course_id", "category_id", "title", "normalized_title", "course_url", "enrol_url", "summary_text", "summary_html", "teachers_json", "detected_codes_json", "detected_terms_json", "self_enrol_available", "guest_access", "limit_mentioned", "limit_text", "participant_limit_value", "raw_json") VALUES (10, 1, '1476', '235', 'ML4520 Ethics and Philosophy of Machine Learning', 'ml4520 ethics and philosophy of machine learning', 'https://moodle.zdv.uni-tuebingen.de/course/view.php?id=1476', 'https://moodle.zdv.uni-tuebingen.de/enrol/index.php?id=1476', 'Algorithmic systems are tools of governance when they are used to determine how social roles are assigned and how social goods are distributed. They influence the support unemployed receive; how health care resources are allocated among patients; and whether prisoners are released or detained before trial. As companies and public administrations entrust increasingly significant predictions and decisions to algorithmic systems, data scientists and machine learning practitioners are empowered to determine aspects of the structure of our societies. Attending their rise in power and prestige is a growing chorus of critics calling for fairness, justice, and democratic accountability in algorithmic decision-making. These developments are, in their technological aspect, unprecedented. At the same time, the questions they raise concerning the just distribution of social goods and roles belong to the most traditional areas of philosophical inquiry. This course introduces students to (1) recent technical literature in algorithmic fairness, (2) empirical evaluations of allocation mechanisms, and (3) classic philosophical work on the just distribution of social roles and goods. We stress the continuity between contemporary problems in algorithmic fairness and similar difficulties that predate machine learning. Engaging with literature drawn from a wide range of disciplines will present significant challenges but, we hope, yield equally significant rewards. The seminar will be held in English.', '<div class="no-overflow"><p>Algorithmic systems are tools of governance when they are used to determine how social roles are assigned and how social goods are distributed. They influence the support unemployed receive; how health care resources are allocated among patients; and whether prisoners are released or detained before trial. As companies and public administrations entrust increasingly significant predictions and decisions to algorithmic systems, data scientists and machine learning practitioners are empowered to determine aspects of the structure of our societies. Attending their rise in power and prestige is a growing chorus of critics calling for fairness, justice, and democratic accountability in algorithmic decision-making. These developments are, in their technological aspect, unprecedented. At the same time, the questions they raise concerning the just distribution of social goods and roles belong to the most traditional areas of philosophical inquiry.</p> <p>This course introduces students to (1) recent technical literature in algorithmic fairness, (2) empirical evaluations of allocation mechanisms, and (3) classic philosophical work on the just distribution of social roles and goods. We stress the continuity between contemporary problems in algorithmic fairness and similar difficulties that predate machine learning. Engaging with literature drawn from a wide range of disciplines will present significant challenges but, we hope, yield equally significant rewards.</p> <p>The seminar will be held in English.</p></div>', '[{"display_name": "Sebastian Zezulka", "profile_url": "https://moodle.zdv.uni-tuebingen.de/user/profile.php?id=192", "moodle_user_id": "192"}]', '["ML4520"]', '[]', 1, 0, 1, 'This course introduces students to (1) recent technical literature in algorithmic fairness, (2) empirical evaluations of allocation mechanisms, and (3) classic philosophical work on the just distribution of social roles and goods.', NULL, '{"coursebox_classes": ["coursebox", "clearfix", "odd"], "data_type": "1", "course_page_url": "https://moodle.zdv.uni-tuebingen.de/enrol/index.php?id=1476", "enrolment_labels": ["Selbsteinschreibung (Studierende*r)"]}');
INSERT INTO "moodle_courses" ("id", "run_id", "moodle_course_id", "category_id", "title", "normalized_title", "course_url", "enrol_url", "summary_text", "summary_html", "teachers_json", "detected_codes_json", "detected_terms_json", "self_enrol_available", "guest_access", "limit_mentioned", "limit_text", "participant_limit_value", "raw_json") VALUES (11, 1, '1505', '235', 'Einführung in die Logik (INF3483)', 'einführung in die logik (inf3483)', 'https://moodle.zdv.uni-tuebingen.de/course/view.php?id=1505', 'https://moodle.zdv.uni-tuebingen.de/enrol/index.php?id=1505', '', '', '[{"display_name": "Thomas Piecha", "profile_url": "https://moodle.zdv.uni-tuebingen.de/user/profile.php?id=27524", "moodle_user_id": "27524"}, {"display_name": "Eduardo Skapinakis", "profile_url": "https://moodle.zdv.uni-tuebingen.de/user/profile.php?id=27670", "moodle_user_id": "27670"}, {"display_name": "Ezra Felix Lysandro Strupp", "profile_url": "https://moodle.zdv.uni-tuebingen.de/user/profile.php?id=2666", "moodle_user_id": "2666"}]', '["INF3483"]', '[]', 1, 0, 0, NULL, NULL, '{"coursebox_classes": ["coursebox", "clearfix", "even"], "data_type": "1", "course_page_url": "https://moodle.zdv.uni-tuebingen.de/enrol/index.php?id=1505", "enrolment_labels": ["Selbsteinschreibung (Studierende*r)"]}');
INSERT INTO "moodle_courses" ("id", "run_id", "moodle_course_id", "category_id", "title", "normalized_title", "course_url", "enrol_url", "summary_text", "summary_html", "teachers_json", "detected_codes_json", "detected_terms_json", "self_enrol_available", "guest_access", "limit_mentioned", "limit_text", "participant_limit_value", "raw_json") VALUES (12, 1, '1506', '235', 'Effiziente Algorithmen (Proseminar) Sommer 2026', 'effiziente algorithmen (proseminar) sommer 2026', 'https://moodle.zdv.uni-tuebingen.de/course/view.php?id=1506', 'https://moodle.zdv.uni-tuebingen.de/enrol/index.php?id=1506', 'Das Proseminar beinhaltet das Erarbeiten von schriftlichen Quellen unter Betreuung zu Themen aus dem Bereich Effiziente Algorithmen. Die Vorbesprechung findet statt am 16.04. 16:00-18:00 und am 23.04. 8:00-10:00. Das Proseminar wird dann als Blockkurs am 13.+14.06. statt finden.', '<div class="no-overflow"><p>Das Proseminar beinhaltet das Erarbeiten von schriftlichen Quellen unter Betreuung zu Themen aus dem Bereich Effiziente Algorithmen.</p> <p>Die Vorbesprechung findet statt am 16.04. 16:00-18:00 und am 23.04. 8:00-10:00.</p> <p>Das Proseminar wird dann als Blockkurs am 13.+14.06. statt finden.</p></div>', '[{"display_name": "Katharina Klost", "profile_url": "https://moodle.zdv.uni-tuebingen.de/user/profile.php?id=50947", "moodle_user_id": "50947"}]', '[]', '["Sommer 2026"]', 1, 0, 0, NULL, NULL, '{"coursebox_classes": ["coursebox", "clearfix", "odd"], "data_type": "1", "course_page_url": "https://moodle.zdv.uni-tuebingen.de/enrol/index.php?id=1506", "enrolment_labels": ["Selbsteinschreibung (Studierende*r)"]}');
INSERT INTO "moodle_courses" ("id", "run_id", "moodle_course_id", "category_id", "title", "normalized_title", "course_url", "enrol_url", "summary_text", "summary_html", "teachers_json", "detected_codes_json", "detected_terms_json", "self_enrol_available", "guest_access", "limit_mentioned", "limit_text", "participant_limit_value", "raw_json") VALUES (13, 1, '1509', '235', 'Machine Learning for Health 2026', 'machine learning for health 2026', 'https://moodle.zdv.uni-tuebingen.de/course/view.php?id=1509', 'https://moodle.zdv.uni-tuebingen.de/enrol/index.php?id=1509', 'This seminar covers different machine learning methods on biomedical data.', '<div class="no-overflow"><p>This seminar covers different machine learning methods on biomedical data.</p></div>', '[{"display_name": "Ralf Eggeling", "profile_url": "https://moodle.zdv.uni-tuebingen.de/user/profile.php?id=23", "moodle_user_id": "23"}]', '[]', '[]', 1, 0, 0, NULL, NULL, '{"coursebox_classes": ["coursebox", "clearfix", "even"], "data_type": "1", "course_page_url": "https://moodle.zdv.uni-tuebingen.de/enrol/index.php?id=1509", "enrolment_labels": ["Selbsteinschreibung (Studierende*r)"]}');
INSERT INTO "moodle_courses" ("id", "run_id", "moodle_course_id", "category_id", "title", "normalized_title", "course_url", "enrol_url", "summary_text", "summary_html", "teachers_json", "detected_codes_json", "detected_terms_json", "self_enrol_available", "guest_access", "limit_mentioned", "limit_text", "participant_limit_value", "raw_json") VALUES (14, 1, '1524', '235', 'Seminar: Algorithmische Graphentheorie', 'seminar: algorithmische graphentheorie', 'https://moodle.zdv.uni-tuebingen.de/course/view.php?id=1524', 'https://moodle.zdv.uni-tuebingen.de/enrol/index.php?id=1524', 'Theoretische Informatik (Seminar): Algorithmische Graphentheorie We deal with advanced topics in Algorithmic Graph Theory. More precisely, we will read and present different papers from various well-known conferences in algorithms and theoretical computer science. The papers deal with ordered graph decomposition, drawings with integer length, Laman graphs,... The first meeting will take place on Monday 13th of April in room A222 (MvL1).', '<div class="no-overflow"><p>Theoretische Informatik (Seminar): Algorithmische Graphentheorie</p> <p>We deal with advanced topics in Algorithmic Graph Theory. More precisely, we will read and present different papers from various well-known conferences in algorithms and theoretical computer science. The papers deal with ordered graph decomposition, drawings with integer length, Laman graphs,...</p> <p>The first meeting will take place on Monday 13th of April in room A222 (MvL1).</p></div>', '[{"display_name": "Lena Marie Schlipf", "profile_url": "https://moodle.zdv.uni-tuebingen.de/user/profile.php?id=197", "moodle_user_id": "197"}]', '[]', '[]', 1, 0, 0, NULL, NULL, '{"coursebox_classes": ["coursebox", "clearfix", "odd", "first"], "data_type": "1", "course_page_url": "https://moodle.zdv.uni-tuebingen.de/enrol/index.php?id=1524", "enrolment_labels": ["Selbsteinschreibung (Studierende*r)"]}');
INSERT INTO "moodle_courses" ("id", "run_id", "moodle_course_id", "category_id", "title", "normalized_title", "course_url", "enrol_url", "summary_text", "summary_html", "teachers_json", "detected_codes_json", "detected_terms_json", "self_enrol_available", "guest_access", "limit_mentioned", "limit_text", "participant_limit_value", "raw_json") VALUES (15, 1, '1525', '235', 'Seminar: Algorithmische Geometrie - Aktuelle Themen', 'seminar: algorithmische geometrie - aktuelle themen', 'https://moodle.zdv.uni-tuebingen.de/course/view.php?id=1525', 'https://moodle.zdv.uni-tuebingen.de/enrol/index.php?id=1525', 'Theoretische Informatik (Seminar). Wir beschäftigen uns mit aktuellen Themen aus der Algorithmischen Geometrie Blockseminar! Die Vorträge finden Ende September statt We deal with advanced topics in Computational Geometry. More precisely, we will read and present different papers from various well-known conferences in Computational Geometry. The papers deal with lower bounds, Fréchet distance, visibility problems...', '<div class="no-overflow"><p>Theoretische Informatik (Seminar). Wir beschäftigen uns mit aktuellen Themen aus der Algorithmischen Geometrie</p> <p>Blockseminar! Die Vorträge finden Ende September statt</p> <p></p> <div>We deal with advanced topics in Computational Geometry.</div> <div>More precisely, we will read and present different papers from various well-known conferences in Computational Geometry. The papers deal with lower bounds, Fréchet distance, visibility problems...</div></div>', '[{"display_name": "Lena Marie Schlipf", "profile_url": "https://moodle.zdv.uni-tuebingen.de/user/profile.php?id=197", "moodle_user_id": "197"}]', '[]', '[]', 1, 0, 0, NULL, NULL, '{"coursebox_classes": ["coursebox", "clearfix", "even", "last"], "data_type": "1", "course_page_url": "https://moodle.zdv.uni-tuebingen.de/enrol/index.php?id=1525", "enrolment_labels": ["Selbsteinschreibung (Studierende*r)"]}');
INSERT INTO "moodle_courses" ("id", "run_id", "moodle_course_id", "category_id", "title", "normalized_title", "course_url", "enrol_url", "summary_text", "summary_html", "teachers_json", "detected_codes_json", "detected_terms_json", "self_enrol_available", "guest_access", "limit_mentioned", "limit_text", "participant_limit_value", "raw_json") VALUES (16, 1, '1528', '235', 'Datenstrukturen', 'datenstrukturen', 'https://moodle.zdv.uni-tuebingen.de/course/view.php?id=1528', 'https://moodle.zdv.uni-tuebingen.de/enrol/index.php?id=1528', 'In diesem Modul geht es um (fortgeschrittene) Datenstrukturen. Viele Lösungen für algorithmische Probleme basieren auf effizienten Datenstrukturen. Die Studierenden lernen unter anderem Themen wie amortisierte Analyse, Prioritätswarteschlangen, erweiterte Suchbäume und Datenstrukturen für geometrische Probleme kennen.', '<div class="no-overflow"><p>In diesem Modul geht es um (fortgeschrittene) Datenstrukturen. Viele Lösungen für algorithmische Probleme basieren auf effizienten Datenstrukturen. Die Studierenden lernen unter anderem Themen wie amortisierte Analyse, Prioritätswarteschlangen, erweiterte Suchbäume und Datenstrukturen für geometrische Probleme kennen.</p></div>', '[{"display_name": "Katharina Klost", "profile_url": "https://moodle.zdv.uni-tuebingen.de/user/profile.php?id=50947", "moodle_user_id": "50947"}]', '[]', '[]', 1, 0, 0, NULL, NULL, '{"coursebox_classes": ["coursebox", "clearfix", "odd"], "data_type": "1", "course_page_url": "https://moodle.zdv.uni-tuebingen.de/enrol/index.php?id=1528", "enrolment_labels": ["Selbsteinschreibung (Studierende*r)"]}');
INSERT INTO "moodle_courses" ("id", "run_id", "moodle_course_id", "category_id", "title", "normalized_title", "course_url", "enrol_url", "summary_text", "summary_html", "teachers_json", "detected_codes_json", "detected_terms_json", "self_enrol_available", "guest_access", "limit_mentioned", "limit_text", "participant_limit_value", "raw_json") VALUES (17, 1, '1531', '235', 'Network Softwarization SoSe26', 'network softwarization sose26', 'https://moodle.zdv.uni-tuebingen.de/course/view.php?id=1531', 'https://moodle.zdv.uni-tuebingen.de/enrol/index.php?id=1531', 'Die Vorlesung gibt einen Überblick über relevante Technologien im Bereich Network Softwarization. Dazu gehören Software-Defined Networking mittels OpenFlow, Data Plane Programming mittels P4 sowie Virtualisierungstechniken und Network Function Virtualization. Zusätzlich werden aktuelle Forschungsthemen besprochen. Die Veranstaltung wird durch praktische Übungsprojekte begleitet, in denen die Studierenden die erlernten Technologien anwenden und anspruchsvolle Programmieraufgaben lösen.', '<div class="no-overflow"><p dir="ltr" id="yui_3_18_1_1_1736239474486_921" style="text-align: left;">Die Vorlesung gibt einen Überblick über relevante Technologien im Bereich Network Softwarization. Dazu gehören Software-Defined Networking mittels OpenFlow, Data Plane Programming mittels P4 sowie Virtualisierungstechniken und Network Function Virtualization. Zusätzlich werden aktuelle Forschungsthemen besprochen. Die Veranstaltung wird durch praktische Übungsprojekte begleitet, in denen die Studierenden die erlernten Technologien anwenden und anspruchsvolle Programmieraufgaben lösen.</p></div>', '[{"display_name": "Moritz Flüchter", "profile_url": "https://moodle.zdv.uni-tuebingen.de/user/profile.php?id=294", "moodle_user_id": "294"}, {"display_name": "Fabian Ihle", "profile_url": "https://moodle.zdv.uni-tuebingen.de/user/profile.php?id=14375", "moodle_user_id": "14375"}, {"display_name": "Michael Menth", "profile_url": "https://moodle.zdv.uni-tuebingen.de/user/profile.php?id=160", "moodle_user_id": "160"}, {"display_name": "Benjamin Steinert", "profile_url": "https://moodle.zdv.uni-tuebingen.de/user/profile.php?id=29898", "moodle_user_id": "29898"}, {"display_name": "Etienne Laurent Zink", "profile_url": "https://moodle.zdv.uni-tuebingen.de/user/profile.php?id=63", "moodle_user_id": "63"}]', '[]', '["SoSe26"]', 1, 0, 0, NULL, NULL, '{"coursebox_classes": ["coursebox", "clearfix", "even"], "data_type": "1", "course_page_url": "https://moodle.zdv.uni-tuebingen.de/enrol/index.php?id=1531", "enrolment_labels": ["Selbsteinschreibung (Studierende*r)"]}');
INSERT INTO "moodle_courses" ("id", "run_id", "moodle_course_id", "category_id", "title", "normalized_title", "course_url", "enrol_url", "summary_text", "summary_html", "teachers_json", "detected_codes_json", "detected_terms_json", "self_enrol_available", "guest_access", "limit_mentioned", "limit_text", "participant_limit_value", "raw_json") VALUES (18, 1, '1545', '235', 'INFO-4348 Communication Technologies (SoSe26)', 'info-4348 communication technologies (sose26)', 'https://moodle.zdv.uni-tuebingen.de/course/view.php?id=1545', 'https://moodle.zdv.uni-tuebingen.de/enrol/index.php?id=1545', 'Die Vorlesung vermittelt Kenntnisse zu fortgeschrittenen Themen im Bereich Kommunikationsnetze, im Gegensatz zu INF3331 “Grundlagen des Internets” behandelt diese Vorlesung v.a. die Kommunikationsschichten unterhalb des Netzwerk Layers. Themen sind: Daten und Signale, Umwandlung von Daten in digitale Signale, Modulation von digitalen und analogen Signalen, Multiplex-Techniken, Übertragungsmedien, Switching, Data Link Control, Multiple Access Protokolle, Ethernet, Backbone-Konzepte, VLANs, Software-Defined Networking, Quality of Service, Time-Sensitive Networking (TSN), Bussysteme im Fahrzeug und Mobilfunknetzwerke.', '<div class="no-overflow"><p>Die Vorlesung vermittelt Kenntnisse zu fortgeschrittenen Themen im Bereich Kommunikationsnetze, im Gegensatz zu INF3331 “Grundlagen des Internets” behandelt diese Vorlesung v.a. die Kommunikationsschichten unterhalb des Netzwerk Layers.</p> <p>Themen sind: Daten und Signale, Umwandlung von Daten in digitale Signale, Modulation von digitalen und analogen Signalen, Multiplex-Techniken, Übertragungsmedien, Switching, Data Link Control, Multiple Access Protokolle, Ethernet, Backbone-Konzepte, VLANs, Software-Defined Networking, Quality of Service, Time-Sensitive Networking (TSN), Bussysteme im Fahrzeug und Mobilfunknetzwerke.</p></div>', '[{"display_name": "Michael Menth", "profile_url": "https://moodle.zdv.uni-tuebingen.de/user/profile.php?id=160", "moodle_user_id": "160"}, {"display_name": "Lukas Osswald", "profile_url": "https://moodle.zdv.uni-tuebingen.de/user/profile.php?id=77", "moodle_user_id": "77"}, {"display_name": "Oliver Richter", "profile_url": "https://moodle.zdv.uni-tuebingen.de/user/profile.php?id=54135", "moodle_user_id": "54135"}]', '["INFO4348"]', '["SoSe26"]', 1, 0, 0, NULL, NULL, '{"coursebox_classes": ["coursebox", "clearfix", "odd"], "data_type": "1", "course_page_url": "https://moodle.zdv.uni-tuebingen.de/enrol/index.php?id=1545", "enrolment_labels": ["Selbsteinschreibung (Studierende*r)"]}');
INSERT INTO "moodle_courses" ("id", "run_id", "moodle_course_id", "category_id", "title", "normalized_title", "course_url", "enrol_url", "summary_text", "summary_html", "teachers_json", "detected_codes_json", "detected_terms_json", "self_enrol_available", "guest_access", "limit_mentioned", "limit_text", "participant_limit_value", "raw_json") VALUES (19, 1, '1558', '235', 'Mobile Robots (Robotics II)', 'mobile robots (robotics ii)', 'https://moodle.zdv.uni-tuebingen.de/course/view.php?id=1558', 'https://moodle.zdv.uni-tuebingen.de/enrol/index.php?id=1558', 'The Mobile Robots module focuses in particular on wheel-driven robots and flying robots: introduction, mathematical basics, kinematic modeling of wheel-driven mobile robots, sensors for mobile robots, mapping, localization, navigation of mobile robots and modeling of flying robots.', '<div class="no-overflow"><p>The Mobile Robots module focuses in particular on wheel-driven robots and flying robots: introduction, mathematical basics, kinematic modeling of wheel-driven mobile robots, sensors for mobile robots, mapping, localization, navigation of mobile robots and modeling of flying robots.</p></div>', '[{"display_name": "Max Beffert", "profile_url": "https://moodle.zdv.uni-tuebingen.de/user/profile.php?id=13570", "moodle_user_id": "13570"}, {"display_name": "David Joseph", "profile_url": "https://moodle.zdv.uni-tuebingen.de/user/profile.php?id=28352", "moodle_user_id": "28352"}, {"display_name": "Yuzhi Lai", "profile_url": "https://moodle.zdv.uni-tuebingen.de/user/profile.php?id=14874", "moodle_user_id": "14874"}, {"display_name": "Andreas Zell", "profile_url": "https://moodle.zdv.uni-tuebingen.de/user/profile.php?id=13755", "moodle_user_id": "13755"}]', '[]', '[]', 1, 0, 0, NULL, NULL, '{"coursebox_classes": ["coursebox", "clearfix", "even"], "data_type": "1", "course_page_url": "https://moodle.zdv.uni-tuebingen.de/enrol/index.php?id=1558", "enrolment_labels": ["Selbsteinschreibung (Studierende*r)"]}');
INSERT INTO "moodle_courses" ("id", "run_id", "moodle_course_id", "category_id", "title", "normalized_title", "course_url", "enrol_url", "summary_text", "summary_html", "teachers_json", "detected_codes_json", "detected_terms_json", "self_enrol_available", "guest_access", "limit_mentioned", "limit_text", "participant_limit_value", "raw_json") VALUES (20, 1, '1559', '235', 'Introduction to Neural Networks', 'introduction to neural networks', 'https://moodle.zdv.uni-tuebingen.de/course/view.php?id=1559', 'https://moodle.zdv.uni-tuebingen.de/enrol/index.php?id=1559', 'After a short introduction to the biological foundations of neural networks, the most important algorithms of artificial neural networks and their underlying theory will be introduced. In the assignment sheets, you will apply and deepen the acquired knowledge in theoretical and practical tasks.', '<div class="no-overflow"><p>After a short introduction to the biological foundations of neural networks, the most important algorithms of artificial neural networks and their underlying theory will be introduced.</p> <p>In the assignment sheets, you will apply and deepen the acquired knowledge in theoretical and practical tasks.</p></div>', '[{"display_name": "Dominik Hildebrand", "profile_url": "https://moodle.zdv.uni-tuebingen.de/user/profile.php?id=29713", "moodle_user_id": "29713"}, {"display_name": "Rafia Rahim", "profile_url": "https://moodle.zdv.uni-tuebingen.de/user/profile.php?id=16233", "moodle_user_id": "16233"}, {"display_name": "Andreas Zell", "profile_url": "https://moodle.zdv.uni-tuebingen.de/user/profile.php?id=13755", "moodle_user_id": "13755"}]', '[]', '[]', 1, 0, 0, NULL, NULL, '{"coursebox_classes": ["coursebox", "clearfix", "odd"], "data_type": "1", "course_page_url": "https://moodle.zdv.uni-tuebingen.de/enrol/index.php?id=1559", "enrolment_labels": ["Selbsteinschreibung (Studierende*r)"]}');
INSERT INTO "moodle_courses" ("id", "run_id", "moodle_course_id", "category_id", "title", "normalized_title", "course_url", "enrol_url", "summary_text", "summary_html", "teachers_json", "detected_codes_json", "detected_terms_json", "self_enrol_available", "guest_access", "limit_mentioned", "limit_text", "participant_limit_value", "raw_json") VALUES (21, 1, '1561', '235', 'Mathematik für Informatik 2: Lineare Algebra', 'mathematik für informatik 2: lineare algebra', 'https://moodle.zdv.uni-tuebingen.de/course/view.php?id=1561', 'https://moodle.zdv.uni-tuebingen.de/enrol/index.php?id=1561', 'Willkommen zur Vorlesung Mathematik für Infor matik 2 ( Lineare Algebra )! Eine Anmeldung vor Vorlesungsbeginn ist nicht nötig. Die erste Vorlesung findet am Montag, 13.4.2026, 10:15 bis 12:00 Uhr im Hörsaal N06 auf der Morgenstelle (Hörsaalzentrum) statt. Alle weiteren Informationen (Einschreibeschlüssel für Moodle, Termine und Anmeldung für die Übungsgruppen, Prüfungsmodalitäten und vieles mehr) werden dort bekannt gegeben.', '<div class="no-overflow"><div>Willkommen zur Vorlesung Mathematik für Infor<wbr/>matik 2 (<span class="il">Lineare</span> <span class="il">Algebra</span>)!</div> <div>Eine Anmeldung vor Vorlesungsbeginn ist nicht nötig. </div> <div>Die erste Vorlesung findet am Montag, 13.4.2026, 10:15 bis 12:00 Uhr im Hörsaal N06 auf der Morgenstelle (Hörsaalzentrum) statt. Alle weiteren Informationen (Einschreibeschlüssel für Moodle, Termine und Anmeldung für die <wbr/>Übungsgruppen, Prüfungsmodalitäten und vieles mehr) werden dort bekannt gegeben.</div></div>', '[{"display_name": "Britta Dorn", "profile_url": "https://moodle.zdv.uni-tuebingen.de/user/profile.php?id=1829", "moodle_user_id": "1829"}, {"display_name": "Paco Samuel Schatz", "profile_url": "https://moodle.zdv.uni-tuebingen.de/user/profile.php?id=1891", "moodle_user_id": "1891"}]', '[]', '[]', 1, 0, 0, NULL, NULL, '{"coursebox_classes": ["coursebox", "clearfix", "even"], "data_type": "1", "course_page_url": "https://moodle.zdv.uni-tuebingen.de/enrol/index.php?id=1561", "enrolment_labels": ["Selbsteinschreibung (Studierende*r)"]}');
INSERT INTO "moodle_courses" ("id", "run_id", "moodle_course_id", "category_id", "title", "normalized_title", "course_url", "enrol_url", "summary_text", "summary_html", "teachers_json", "detected_codes_json", "detected_terms_json", "self_enrol_available", "guest_access", "limit_mentioned", "limit_text", "participant_limit_value", "raw_json") VALUES (22, 1, '1571', '235', 'Einführung in die klinische Neurowissenschaft - Teil 2: Das periphere Nervensystem', 'einführung in die klinische neurowissenschaft - teil 2: das periphere nervensystem', 'https://moodle.zdv.uni-tuebingen.de/course/view.php?id=1571', 'https://moodle.zdv.uni-tuebingen.de/enrol/index.php?id=1571', 'Ohne das periphere Nervensystem (PNS) - "die Nerven" - funktoniert im Organismus nichts. Die Nerven verbinden Gehirn und Rückenmark, also das Zentralnervensystem, mit den Organen. Dabei leitet das motorische System die Willkürmotorik vom Zentrum zur Peripherie und ermöglicht Bewegung und Kraftentwicklung der Muskulatur. Das sensorische/sensible System leitet umgekehrt von der Peripherie ans Zentrum Wahrnehmungen wie Temperatur- und Schmerzempfindung. Das autonome Nervensystem schließlich - Sympathikus und Parasympathikus - vermittelt die Funktionen, die für Gesundheit und Leben essentiell sind, ohne dass uns das bewusst wird. Es hält zum Beispiel den Blutdruck konstant, wenn wir vom Liegen aufstehen, so dass wir nicht ohnmächtig werden. Wir werden uns zunächst mit dem anatomischen Bau und der elektrophysiologischen Funktionsweise des gesunden peripheren Nervensystems beschäftigen. Danach werden wir die wichtigsten Krankheiten und ihre Therapiemöglichkeiten besprechen. Lernziele - Kenntnis von Struktur und elektrophysiologischer Funktionsweise des normalen PNS - Verständnis dafür, wie Krankheitsursachen - Infektionen, Gifte u.a. - die Struktur und Funktion des PNS stören - Verständnis für die daraus abgeleiteten Überlegungen zur Therapie Die Veranstaltung kann unabhängig von der im WS 25/26 abgehaltenen Veranstaltung "Einführung in die klinische Neurowissenschaft - das Zentralnervensystem" besucht werden.', '<div class="no-overflow"><p>Ohne das periphere Nervensystem (PNS) - "die Nerven" - funktoniert im Organismus nichts. Die Nerven verbinden Gehirn und Rückenmark, also das Zentralnervensystem, mit den Organen. Dabei leitet das motorische System die Willkürmotorik vom Zentrum zur Peripherie und ermöglicht Bewegung und Kraftentwicklung der Muskulatur. Das sensorische/sensible System leitet umgekehrt von der Peripherie ans Zentrum Wahrnehmungen wie Temperatur- und Schmerzempfindung. Das autonome Nervensystem schließlich - Sympathikus und Parasympathikus - vermittelt die Funktionen, die für Gesundheit und Leben essentiell sind, ohne dass uns das bewusst wird. Es hält zum Beispiel den Blutdruck konstant, wenn wir vom Liegen aufstehen, so dass wir nicht ohnmächtig werden.</p> <p>Wir werden uns zunächst mit dem anatomischen Bau und der elektrophysiologischen Funktionsweise des gesunden peripheren Nervensystems beschäftigen. Danach werden wir die wichtigsten Krankheiten und ihre Therapiemöglichkeiten besprechen. </p> <p>Lernziele</p> <p> - Kenntnis von Struktur und elektrophysiologischer Funktionsweise des normalen PNS</p> <p> - Verständnis dafür, wie Krankheitsursachen - Infektionen, Gifte u.a. - die Struktur und Funktion des PNS stören</p> <p> - Verständnis für die daraus abgeleiteten Überlegungen zur Therapie</p> <p></p> <p>Die Veranstaltung kann unabhängig von der im WS 25/26 abgehaltenen Veranstaltung "Einführung in die klinische Neurowissenschaft - das Zentralnervensystem" besucht werden. </p></div>', '[{"display_name": "Antje Bornemann", "profile_url": "https://moodle.zdv.uni-tuebingen.de/user/profile.php?id=13697", "moodle_user_id": "13697"}]', '[]', '["WS 25/26"]', 1, 0, 0, NULL, NULL, '{"coursebox_classes": ["coursebox", "clearfix", "odd"], "data_type": "1", "course_page_url": "https://moodle.zdv.uni-tuebingen.de/enrol/index.php?id=1571", "enrolment_labels": ["Selbsteinschreibung (Studierende*r)"]}');
INSERT INTO "moodle_courses" ("id", "run_id", "moodle_course_id", "category_id", "title", "normalized_title", "course_url", "enrol_url", "summary_text", "summary_html", "teachers_json", "detected_codes_json", "detected_terms_json", "self_enrol_available", "guest_access", "limit_mentioned", "limit_text", "participant_limit_value", "raw_json") VALUES (23, 1, '1572', '235', 'Entwicklung der Programmiersprache Java SoSe 2026', 'entwicklung der programmiersprache java sose 2026', 'https://moodle.zdv.uni-tuebingen.de/course/view.php?id=1572', 'https://moodle.zdv.uni-tuebingen.de/enrol/index.php?id=1572', 'Seit den 1990iger Jahren werden Eigenschaften, die aus funktionalen Programmiersprachen bekannt sind, in objektorientierte Sprachen übernommen. In diesem Seminar wird die Entwicklung der Programmiersprache Java aufgezeigt. Eine erste Erweiterung von Java, die Eigenschaften funktionaler Sprachen übernommen hat, war PIZZA. PIZZA hatte parametrische Polymorphie, Funktionen höherer Ordnung und algebraische Datentypen. In Java 5 wurde die parametrische Polymorphie, erweitert durch use-site Varianz, übernommen. In Java 8 kamen schließlich Lambda-Ausdrücke hinzu. Die Eigenschaft Typinferenz, die funktionale Sprachen sehr flexibel macht, ist in Java nur sehr eingeschränkt verfügbar. Die Erweiterung Java-TX verfügt über einen globalen Typinferenzalgorithmus, der es ermöglicht, Java Code ohne jede Typangabe, bei gleichzeitiger voller statischer Typsicherheit, zu schreiben. Jedes dieser Themen wird durch einen Teilnehmende aufgegriffen und in einer Präsenation zur Diskussion gestellt.', '<div class="no-overflow"><p>Seit den 1990iger Jahren werden Eigenschaften, die aus funktionalen Programmiersprachen bekannt sind, in objektorientierte Sprachen übernommen. In diesem Seminar wird die Entwicklung der Programmiersprache Java aufgezeigt. Eine erste Erweiterung von Java, die Eigenschaften funktionaler Sprachen übernommen hat, war PIZZA. PIZZA hatte parametrische Polymorphie, Funktionen höherer Ordnung und algebraische Datentypen. In Java 5 wurde die parametrische Polymorphie, erweitert durch use-site Varianz, übernommen. In Java 8 kamen schließlich Lambda-Ausdrücke hinzu. Die Eigenschaft Typinferenz, die funktionale Sprachen sehr flexibel macht, ist in Java nur sehr eingeschränkt verfügbar. Die Erweiterung Java-TX verfügt über einen globalen Typinferenzalgorithmus, der es ermöglicht, Java Code ohne jede Typangabe, bei gleichzeitiger voller statischer Typsicherheit, zu schreiben.<br/>Jedes dieser Themen wird durch einen Teilnehmende aufgegriffen und in einer Präsenation zur Diskussion gestellt.</p></div>', '[{"display_name": "Martin Andreas Plümicke", "profile_url": "https://moodle.zdv.uni-tuebingen.de/user/profile.php?id=1003", "moodle_user_id": "1003"}]', '[]', '["SoSe 2026"]', 1, 0, 0, NULL, NULL, '{"coursebox_classes": ["coursebox", "clearfix", "even"], "data_type": "1", "course_page_url": "https://moodle.zdv.uni-tuebingen.de/enrol/index.php?id=1572", "enrolment_labels": ["Selbsteinschreibung (Studierende*r)"]}');
INSERT INTO "moodle_courses" ("id", "run_id", "moodle_course_id", "category_id", "title", "normalized_title", "course_url", "enrol_url", "summary_text", "summary_html", "teachers_json", "detected_codes_json", "detected_terms_json", "self_enrol_available", "guest_access", "limit_mentioned", "limit_text", "participant_limit_value", "raw_json") VALUES (24, 1, '1579', '235', 'Einführung Internettechnologien SoSe 26', 'einführung internettechnologien sose 26', 'https://moodle.zdv.uni-tuebingen.de/course/view.php?id=1579', 'https://moodle.zdv.uni-tuebingen.de/enrol/index.php?id=1579', '', '', '[{"display_name": "Torsten Kockler", "profile_url": "https://moodle.zdv.uni-tuebingen.de/user/profile.php?id=3049", "moodle_user_id": "3049"}, {"display_name": "Kevin Körner", "profile_url": "https://moodle.zdv.uni-tuebingen.de/user/profile.php?id=268", "moodle_user_id": "268"}, {"display_name": "Thomas Walter", "profile_url": "https://moodle.zdv.uni-tuebingen.de/user/profile.php?id=1527", "moodle_user_id": "1527"}]', '[]', '["SoSe 26"]', 1, 0, 0, NULL, NULL, '{"coursebox_classes": ["coursebox", "clearfix", "odd"], "data_type": "1", "course_page_url": "https://moodle.zdv.uni-tuebingen.de/enrol/index.php?id=1579", "enrolment_labels": ["Selbsteinschreibung (Studierende*r)"]}');
INSERT INTO "moodle_courses" ("id", "run_id", "moodle_course_id", "category_id", "title", "normalized_title", "course_url", "enrol_url", "summary_text", "summary_html", "teachers_json", "detected_codes_json", "detected_terms_json", "self_enrol_available", "guest_access", "limit_mentioned", "limit_text", "participant_limit_value", "raw_json") VALUES (25, 1, '1580', '235', 'Dynamische virtuelle Welten SoSe 26', 'dynamische virtuelle welten sose 26', 'https://moodle.zdv.uni-tuebingen.de/course/view.php?id=1580', 'https://moodle.zdv.uni-tuebingen.de/enrol/index.php?id=1580', 'Virtuelle Welten sind aus der modernen Welt nicht mehr wegzudenken: Interaktives Storytelling, virtuelle Museumsausstellungen und Computerspiele verwenden als Basis virtuelle Welten, in denen dreidimensionale, interaktive Objekte integriert werden. Die Grundlagen um eine dynamische, interaktive, virtuelle Welt zu erstellen, werden in diesem Kurs vermittelt. Der Kurs vermittelt die Grundlagen der Erstellung dreidimensionaler virtueller Welten anhand der GameEngine Unity. Folgende Themenfelder werden in der Veranstaltung behandelt: Grundlegende Bedienung des Unity Editors Konzeption virtueller Welten Realisierung virtueller Welten in Unity Entwicklung interaktiver Elemente in virtuellen Welten Bewegte Objekte mittels 3D-Animationen Ausgewählte Programmierung Exportieren erstellter Welten auf ausgewählte Zielplattformen', '<div class="no-overflow"><p>Virtuelle Welten sind aus der modernen Welt nicht mehr wegzudenken: Interaktives Storytelling, virtuelle Museumsausstellungen und Computerspiele verwenden als Basis virtuelle Welten, in denen dreidimensionale, interaktive Objekte integriert werden. Die Grundlagen um eine dynamische, interaktive, virtuelle Welt zu erstellen, werden in diesem Kurs vermittelt.</p> <p>Der Kurs vermittelt die Grundlagen der Erstellung dreidimensionaler virtueller Welten anhand der GameEngine Unity. Folgende Themenfelder werden in der Veranstaltung behandelt:</p> <ul> <li>Grundlegende Bedienung des Unity Editors</li> <li>Konzeption virtueller Welten</li> <li>Realisierung virtueller Welten in Unity</li> <li>Entwicklung interaktiver Elemente in virtuellen Welten</li> <li>Bewegte Objekte mittels 3D-Animationen</li> <li>Ausgewählte Programmierung</li> <li>Exportieren erstellter Welten auf ausgewählte Zielplattformen</li> </ul></div>', '[{"display_name": "Kevin Körner", "profile_url": "https://moodle.zdv.uni-tuebingen.de/user/profile.php?id=268", "moodle_user_id": "268"}]', '[]', '["SoSe 26"]', 1, 0, 0, NULL, NULL, '{"coursebox_classes": ["coursebox", "clearfix", "even"], "data_type": "1", "course_page_url": "https://moodle.zdv.uni-tuebingen.de/enrol/index.php?id=1580", "enrolment_labels": ["Selbsteinschreibung (Studierende*r)"]}');
INSERT INTO "moodle_courses" ("id", "run_id", "moodle_course_id", "category_id", "title", "normalized_title", "course_url", "enrol_url", "summary_text", "summary_html", "teachers_json", "detected_codes_json", "detected_terms_json", "self_enrol_available", "guest_access", "limit_mentioned", "limit_text", "participant_limit_value", "raw_json") VALUES (26, 1, '1581', '235', 'VR Erleben SoSe 26', 'vr erleben sose 26', 'https://moodle.zdv.uni-tuebingen.de/course/view.php?id=1581', 'https://moodle.zdv.uni-tuebingen.de/enrol/index.php?id=1581', 'Virtuelle Welten sind aus der modernen Welt nicht mehr wegzudenken: Interaktives Storytelling, virtuelle Museumsausstellungen und Computerspiele verwenden als Basis virtuelle Welten, in denen dreidimensionale, interaktive Objekte integriert werden. Die Grundlagen um eine dynamische, interaktive, virtuelle Welt zu erstellen, werden in diesem Kurs vermittelt. ​ ​Der Kurs vermittelt die Grundlagen der Erstellung von Virtual Reality Anwendungen mittels der GameEngine Unity und der OpenXR-Bibliothek. Anhand ausgewählter Beispiele erstellen die Kursteilnehmenden unter Anleitung selbstständig - in Praktikumsform - eigene VR-Anwendungen. Im letzten drittel des Kurses konzipieren die Teilnehmenden individuell ein eigenes VR-Projekt und realisieren dieses mit den erlernten Elementen. Die für den Kurs benötigte Hardware (VR-Brillen) wird bereitgestellt, ggf. rechenstarke Laptops.', '<div class="no-overflow"><p>Virtuelle Welten sind aus der modernen Welt nicht mehr wegzudenken: Interaktives Storytelling, virtuelle Museumsausstellungen und Computerspiele verwenden als Basis virtuelle Welten, in denen dreidimensionale, interaktive Objekte integriert werden. Die Grundlagen um eine dynamische, interaktive, virtuelle Welt zu erstellen, werden in diesem Kurs vermittelt.<br/>​<br/>​Der Kurs vermittelt die Grundlagen der Erstellung von Virtual Reality Anwendungen mittels der GameEngine Unity und der OpenXR-Bibliothek. Anhand ausgewählter Beispiele erstellen die Kursteilnehmenden unter Anleitung selbstständig - in Praktikumsform - eigene VR-Anwendungen. Im letzten drittel des Kurses konzipieren die Teilnehmenden individuell ein eigenes VR-Projekt und realisieren dieses mit den erlernten Elementen.<br/><br/>Die für den Kurs benötigte Hardware (VR-Brillen) wird bereitgestellt, ggf. rechenstarke Laptops.</p></div>', '[{"display_name": "Kevin Körner", "profile_url": "https://moodle.zdv.uni-tuebingen.de/user/profile.php?id=268", "moodle_user_id": "268"}]', '[]', '["SoSe 26"]', 1, 0, 0, NULL, NULL, '{"coursebox_classes": ["coursebox", "clearfix", "odd"], "data_type": "1", "course_page_url": "https://moodle.zdv.uni-tuebingen.de/enrol/index.php?id=1581", "enrolment_labels": ["Selbsteinschreibung (Studierende*r)"]}');
INSERT INTO "moodle_courses" ("id", "run_id", "moodle_course_id", "category_id", "title", "normalized_title", "course_url", "enrol_url", "summary_text", "summary_html", "teachers_json", "detected_codes_json", "detected_terms_json", "self_enrol_available", "guest_access", "limit_mentioned", "limit_text", "participant_limit_value", "raw_json") VALUES (27, 1, '1582', '235', 'NLP: Wort und Lexikon (2026)', 'nlp: wort und lexikon (2026)', 'https://moodle.zdv.uni-tuebingen.de/course/view.php?id=1582', 'https://moodle.zdv.uni-tuebingen.de/enrol/index.php?id=1582', 'Die lexikalische Semantik beschäftigt sich mit der Bedeutung von Lexemen, d.h. von Worten aber auch komplexeren Einheiten, die im Lexikon aufgelistet sind. Im Rahmen der maschinellen Sprachverarbeitungen (NLP) stehen meist bestimmte semantischen Relationen zwischen Lexemen im Vordergrund, also z.B. die Synonym-Beziehung zwischen Mensch und Homo Sapiens , oder die Hyponym-Beziehung zwischen Mensch und Lebewesen . Neben diesen wörtlichen Bedeutungen gibt es aber auch nicht-wörtliche Bedeutungen bei Metaphern, rhetorischen Figuren (Ironie, Sarkasmus, rhetorische Fragen, ...) und festeren idiomatische Ausdrücke, zum Beispiel ins Gras beißen . Dazu zählen außerdem so genannte Konnotationen bestehend aus Gefühlen und Einstellungen ( Hund versus Köter ), die eigentlich immer mit natürlicher Sprache einhergehen, die aber üblicherweise nicht zur wörtlichen Bedeutung gezählt werden. All diese semantischen Informationen sind essentiell für eine Reihe von NLP-Anwendungen, etwa der automatischen Disambiguierung (WSD, Word Sense Disambiguation), die wir in diesem Seminar hauptsächlich betrachten werden. Das Proseminar soll einen Überblick über prominente Konzepte, Ressourcen und Verfahren in diesem zentralen Bereich der NLP verschaffen und setzt keine linguistischen oder computerlinguistischen Kenntnisse voraus. Vorausgesetzt werden aber Kenntnisse in der praktischen und theoretischen Informatik und der Mathematik. Das Proseminar richtet sich daher an fortgeschrittene Bachelorstudierende der Informatik . Qualifikationsziel des Proseminars ist die Fähigkeit, Sachthemen anhand von wissenschaftlicher Literatur zu präsentieren und zu diskutieren. Dafür werden wir in jeder Sitzung einen wissenschaftlichen Text behandeln (ggf. begleitet durch ein Referat), wobei erwartet wird, dass die Teilnehmerinnen und Teilnehmer die Sitzung durch die Lektüre des Textes vorbereitet haben. Die Studien- und Prüfungsleistungen werden durch eine aktive Teilnahme , durch ein Referat und durch eine schriftliche Hausarbeit erbracht.', '<div class="no-overflow"><p>Die lexikalische Semantik beschäftigt sich mit der Bedeutung von Lexemen, d.h. von Worten aber auch komplexeren Einheiten, die im Lexikon aufgelistet sind. Im Rahmen der maschinellen Sprachverarbeitungen (NLP) stehen meist bestimmte semantischen Relationen zwischen Lexemen im Vordergrund, also z.B. die Synonym-Beziehung zwischen <em>Mensch</em> und <em>Homo Sapiens</em>, oder die Hyponym-Beziehung zwischen <em>Mensch</em> und <em>Lebewesen</em>. Neben diesen wörtlichen Bedeutungen gibt es aber auch nicht-wörtliche Bedeutungen bei Metaphern, rhetorischen Figuren (Ironie, Sarkasmus, rhetorische Fragen, ...) und festeren idiomatische Ausdrücke, zum Beispiel <em>ins Gras beißen</em>. Dazu zählen außerdem so genannte Konnotationen bestehend aus Gefühlen und Einstellungen (<em>Hund</em> versus <em>Köter</em>), die eigentlich immer mit natürlicher Sprache einhergehen, die aber üblicherweise nicht zur wörtlichen Bedeutung gezählt werden. All diese semantischen Informationen sind essentiell für eine Reihe von NLP-Anwendungen, etwa der automatischen Disambiguierung (WSD, Word Sense Disambiguation), die wir in diesem Seminar hauptsächlich betrachten werden. <br/><br/>Das Proseminar soll einen Überblick über prominente Konzepte, Ressourcen und Verfahren in diesem zentralen Bereich der NLP verschaffen und setzt keine linguistischen oder computerlinguistischen Kenntnisse voraus. Vorausgesetzt werden aber Kenntnisse in der praktischen und theoretischen Informatik und der Mathematik. Das Proseminar richtet sich daher an <strong>fortgeschrittene Bachelorstudierende der Informatik</strong>. <br/><br/>Qualifikationsziel des Proseminars ist die Fähigkeit, Sachthemen anhand von wissenschaftlicher Literatur zu präsentieren und zu diskutieren. Dafür werden wir in jeder Sitzung einen wissenschaftlichen Text behandeln (ggf. begleitet durch ein Referat), wobei erwartet wird, dass die Teilnehmerinnen und Teilnehmer die Sitzung durch die Lektüre des Textes vorbereitet haben. Die Studien- und Prüfungsleistungen werden durch eine <strong>aktive Teilnahme</strong>, durch ein <strong>Referat</strong> und durch eine <strong>schriftliche Hausarbeit</strong> erbracht.</p></div>', '[{"display_name": "Timm Lichte", "profile_url": "https://moodle.zdv.uni-tuebingen.de/user/profile.php?id=2340", "moodle_user_id": "2340"}]', '[]', '[]', 1, 0, 1, 'begleitet durch ein Referat), wobei erwartet wird, dass die Teilnehmerinnen und Teilnehmer die Sitzung durch die Lektüre des Textes vorbereitet haben.', NULL, '{"coursebox_classes": ["coursebox", "clearfix", "even"], "data_type": "1", "course_page_url": "https://moodle.zdv.uni-tuebingen.de/enrol/index.php?id=1582", "enrolment_labels": ["Selbsteinschreibung (Studierende*r)"]}');
INSERT INTO "moodle_courses" ("id", "run_id", "moodle_course_id", "category_id", "title", "normalized_title", "course_url", "enrol_url", "summary_text", "summary_html", "teachers_json", "detected_codes_json", "detected_terms_json", "self_enrol_available", "guest_access", "limit_mentioned", "limit_text", "participant_limit_value", "raw_json") VALUES (28, 1, '1583', '235', 'NLP: Text und Diskurs (2026)', 'nlp: text und diskurs (2026)', 'https://moodle.zdv.uni-tuebingen.de/course/view.php?id=1583', 'https://moodle.zdv.uni-tuebingen.de/enrol/index.php?id=1583', 'In der Linguistik versteht man unter Text eine "abgegrenzte, zusammenhängende, meist schriftliche sprachliche Äußerung" ( Wikipedia ), mit denen soziale Handlungen vollzogene werden mit dem Ziel, dass der Adressat etwas glaubt oder etwas tut. So verstanden kann ein Text aus nur einem Satz bestehen oder wiederum kleinere Texte enthalten. Im letzteren Fall spricht man allgemeiner auch von einem Diskurs , der z.B. Dialoge zwischen unterschiedlichen Personen einschließen kann. Im Rahmen der maschinellen Sprachverarbeitung (Natural Language Processing, NLP) versucht man, solche Texte und Diskurse automatisch zu analysieren (z.B. beim Spamfilter), zu verändern (z.B. bei der Textvereinfachung) oder zu generieren (z.B. in Question-Answering-Systemen). Das Proseminar soll einen Überblick über prominente Konzepte, Ressourcen und Verfahren in diesem zentralen Bereich der NLP verschaffen und setzt keine linguistischen oder computerlinguistischen Kenntnisse voraus. Vorausgesetzt werden aber Kenntnissen in der praktischen und theoretischen Informatik (insb. formale Sprachentheorie). Das Proseminar richtet sich daher an fortgeschrittene Bachelorstudierende der Informatik .', '<div class="no-overflow"><p>In der Linguistik versteht man unter <strong id="yui_3_18_1_1_1743098929558_942">Text</strong> eine "abgegrenzte, zusammenhängende, meist schriftliche sprachliche Äußerung" (<a href="https://de.wikipedia.org/wiki/Text" id="yui_3_18_1_1_1743098929558_943">Wikipedia</a>), mit denen soziale Handlungen vollzogene werden mit dem Ziel, dass der Adressat etwas glaubt oder etwas tut. So verstanden kann ein Text aus nur einem Satz bestehen oder wiederum kleinere Texte enthalten. Im letzteren Fall spricht man allgemeiner auch von einem <strong>Diskurs</strong>, der z.B. Dialoge zwischen unterschiedlichen Personen einschließen kann. Im Rahmen der <strong>maschinellen Sprachverarbeitung (Natural Language Processing, NLP)</strong> versucht man, solche Texte und Diskurse automatisch zu analysieren (z.B. beim Spamfilter), zu verändern (z.B. bei der Textvereinfachung) oder zu generieren (z.B. in Question-Answering-Systemen). <br/><br/>Das Proseminar soll einen Überblick über prominente Konzepte, Ressourcen und Verfahren in diesem zentralen Bereich der NLP verschaffen und setzt keine linguistischen oder computerlinguistischen Kenntnisse voraus. Vorausgesetzt werden aber Kenntnissen in der praktischen und theoretischen Informatik (insb. formale Sprachentheorie). Das Proseminar richtet sich daher an <strong>fortgeschrittene Bachelorstudierende der Informatik</strong>.</p></div>', '[{"display_name": "Timm Lichte", "profile_url": "https://moodle.zdv.uni-tuebingen.de/user/profile.php?id=2340", "moodle_user_id": "2340"}]', '[]', '[]', 1, 0, 0, NULL, NULL, '{"coursebox_classes": ["coursebox", "clearfix", "odd"], "data_type": "1", "course_page_url": "https://moodle.zdv.uni-tuebingen.de/enrol/index.php?id=1583", "enrolment_labels": ["Selbsteinschreibung (Studierende*r)"]}');
INSERT INTO "moodle_courses" ("id", "run_id", "moodle_course_id", "category_id", "title", "normalized_title", "course_url", "enrol_url", "summary_text", "summary_html", "teachers_json", "detected_codes_json", "detected_terms_json", "self_enrol_available", "guest_access", "limit_mentioned", "limit_text", "participant_limit_value", "raw_json") VALUES (29, 1, '1590', '235', 'Technische Informatik 2: Informatik der Systeme SoSe26', 'technische informatik 2: informatik der systeme sose26', 'https://moodle.zdv.uni-tuebingen.de/course/view.php?id=1590', 'https://moodle.zdv.uni-tuebingen.de/enrol/index.php?id=1590', '', '', '[{"display_name": "Marvin Felix Braun", "profile_url": "https://moodle.zdv.uni-tuebingen.de/user/profile.php?id=54411", "moodle_user_id": "54411"}, {"display_name": "Michael Menth", "profile_url": "https://moodle.zdv.uni-tuebingen.de/user/profile.php?id=160", "moodle_user_id": "160"}, {"display_name": "Gabriel Paradzik", "profile_url": "https://moodle.zdv.uni-tuebingen.de/user/profile.php?id=1288", "moodle_user_id": "1288"}]', '[]', '["SoSe26"]', 1, 0, 0, NULL, NULL, '{"coursebox_classes": ["coursebox", "clearfix", "even"], "data_type": "1", "course_page_url": "https://moodle.zdv.uni-tuebingen.de/enrol/index.php?id=1590", "enrolment_labels": ["Selbsteinschreibung (Studierende*r)"]}');
INSERT INTO "moodle_courses" ("id", "run_id", "moodle_course_id", "category_id", "title", "normalized_title", "course_url", "enrol_url", "summary_text", "summary_html", "teachers_json", "detected_codes_json", "detected_terms_json", "self_enrol_available", "guest_access", "limit_mentioned", "limit_text", "participant_limit_value", "raw_json") VALUES (30, 1, '1605', '235', 'Mobile Robots Practical Course (INF4362) - SS26', 'mobile robots practical course (inf4362) - ss26', 'https://moodle.zdv.uni-tuebingen.de/course/view.php?id=1605', 'https://moodle.zdv.uni-tuebingen.de/enrol/index.php?id=1605', 'In the Mobile Robots lab course, you will gain practical experience in working with mobile robots and develop control algorithms for them. Robots of the type TurtleBot 2 (construction summer 2016) are used as hardware platform. The software for the robots is implemented in C++ . Program and driver infrastructures are realized by the Robot Operating System (ROS2) . The lab course will give you the opportunity to gain experience with sensors, actuators, and control, as well as learn the basics of C++ . The lab course takes place in teams of 2, each assigned to one robot during the semester. Requirements Suitable for 5th semester Bachelor or Master Literature An introduction to C++ for Java programmers (in German): C++ für Java-Programmierer Introduction to ROS: https://docs.ros.org/en/rolling/index.html', '<div class="no-overflow"><p>In the Mobile Robots lab course, you will gain practical experience in working with mobile robots and develop control algorithms for them. Robots of the type <i>TurtleBot 2 </i>(construction summer 2016) are used as hardware platform. The software for the robots is implemented in <i>C++</i>. Program and driver infrastructures are realized by the <i>Robot Operating System (ROS2)</i>. The lab course will give you the opportunity to gain experience with sensors, actuators, and control, as well as learn the basics of <i>C++</i>.</p> <p>The lab course takes place in teams of 2, each assigned to one robot during the semester.</p> <h3>Requirements</h3> <p>Suitable for 5th semester Bachelor or Master</p> <h3>Literature</h3> <p>An introduction to C++ for Java programmers (in German):<br/><a href="http://users.informatik.uni-halle.de/~brass/dbi15/cpp.pdf" rel="noopener" target="_blank">C++ für Java-Programmierer</a><br/>Introduction to ROS:<br/><a class="external-link" href="https://docs.ros.org/en/rolling/index.html" rel="noopener" target="_blank">https://docs.ros.org/en/rolling/index.html</a></p></div>', '[{"display_name": "Genc Ahmeti", "profile_url": "https://moodle.zdv.uni-tuebingen.de/user/profile.php?id=27099", "moodle_user_id": "27099"}, {"display_name": "Daniel Eisele", "profile_url": "https://moodle.zdv.uni-tuebingen.de/user/profile.php?id=2940", "moodle_user_id": "2940"}, {"display_name": "Andreas Zell", "profile_url": "https://moodle.zdv.uni-tuebingen.de/user/profile.php?id=13755", "moodle_user_id": "13755"}]', '["INF4362"]', '["SS26"]', 1, 0, 0, NULL, NULL, '{"coursebox_classes": ["coursebox", "clearfix", "odd"], "data_type": "1", "course_page_url": "https://moodle.zdv.uni-tuebingen.de/enrol/index.php?id=1605", "enrolment_labels": ["Selbsteinschreibung (Studierende*r)"]}');
INSERT INTO "moodle_courses" ("id", "run_id", "moodle_course_id", "category_id", "title", "normalized_title", "course_url", "enrol_url", "summary_text", "summary_html", "teachers_json", "detected_codes_json", "detected_terms_json", "self_enrol_available", "guest_access", "limit_mentioned", "limit_text", "participant_limit_value", "raw_json") VALUES (31, 1, '1630', '235', 'INF3332 - Internet-Praktikum 1 (SoSe 26)', 'inf3332 - internet-praktikum 1 (sose 26)', 'https://moodle.zdv.uni-tuebingen.de/course/view.php?id=1630', 'https://moodle.zdv.uni-tuebingen.de/enrol/index.php?id=1630', 'Das Internetpraktikum findet in den Semesterferien statt. Die Anmeldung zum Praktikum wird gegen Ende der Vorlesungszeit freigeschaltet. Der Beginn der Anmeldephase wird über die info-announce Mailingliste angekündigt. Die Anzahl der Teilnehmer ist beschränkt, es wird ein Auswahlverfahren geben. Der Beitritt zum Moodlekurs zählt als Anmeldung für das Auswahlverfahren. Vorlesung 10.08., Versuche 11.08. - 27.08., Klausur 28.08.', '<div class="no-overflow"><div> <div> <p>Das Internetpraktikum findet in den Semesterferien statt. Die Anmeldung zum Praktikum wird gegen Ende der Vorlesungszeit freigeschaltet. Der Beginn der Anmeldephase wird über die <a href="https://www.fsi.uni-tuebingen.de/mailinglisten/">info-announce</a> Mailingliste angekündigt. Die Anzahl der Teilnehmer ist beschränkt, es wird ein Auswahlverfahren geben. Der Beitritt zum Moodlekurs zählt als Anmeldung für das Auswahlverfahren.</p> <p>Vorlesung 10.08., Versuche 11.08. - 27.08., Klausur 28.08.</p> </div> </div></div>', '[{"display_name": "Moritz Flüchter", "profile_url": "https://moodle.zdv.uni-tuebingen.de/user/profile.php?id=294", "moodle_user_id": "294"}, {"display_name": "Michael Menth", "profile_url": "https://moodle.zdv.uni-tuebingen.de/user/profile.php?id=160", "moodle_user_id": "160"}, {"display_name": "Oliver Richter", "profile_url": "https://moodle.zdv.uni-tuebingen.de/user/profile.php?id=54135", "moodle_user_id": "54135"}]', '["INF3332"]', '["SoSe 26"]', 1, 0, 1, 'Die Anzahl der Teilnehmer ist beschränkt, es wird ein Auswahlverfahren geben.', NULL, '{"coursebox_classes": ["coursebox", "clearfix", "even"], "data_type": "1", "course_page_url": "https://moodle.zdv.uni-tuebingen.de/enrol/index.php?id=1630", "enrolment_labels": ["Selbsteinschreibung (Studierende*r)"]}');
INSERT INTO "moodle_courses" ("id", "run_id", "moodle_course_id", "category_id", "title", "normalized_title", "course_url", "enrol_url", "summary_text", "summary_html", "teachers_json", "detected_codes_json", "detected_terms_json", "self_enrol_available", "guest_access", "limit_mentioned", "limit_text", "participant_limit_value", "raw_json") VALUES (32, 1, '1658', '235', 'Praktikum - Advances in Multimodal Learning SS26', 'praktikum - advances in multimodal learning ss26', 'https://moodle.zdv.uni-tuebingen.de/course/view.php?id=1658', 'https://moodle.zdv.uni-tuebingen.de/enrol/index.php?id=1658', 'General Information This lab project focuses on exploring the challenges in modern Computer Vision and Multimodal Learning algorithms and model development. The project will include a hands-on implementation of various techniques to identify and solve problems, and to evaluate results in comparison to public benchmarks. It will further provide an understanding of the characteristics of models and benchmarks such as generalization and robustness. The project should provide insights on the development of novel Multimodal Learning technology in response to upcoming challenges. Teilnahmevoraussetzungen: ML-4103 Intro-Veranstaltung: 14.04.2025 , 9:00 - 10:00, Mvl1 A301 Ebene 3 Stockwerk 1 To sign up for the lab, please join the intro meeting. I''ll give a tour through the open topics and a rough outline of the timeline and expectations. You will then have one week to decide if this would be for you and on which topic you want to work. If you can not make it to the intro meeting, please send an email to h.kuehne@uni-tuebingen.de .', '<div class="no-overflow"><p class="MsoNormal"><strong><span lang="EN-US">General Information</span></strong></p> <p class="MsoNormal"><span lang="EN-US">This lab project focuses on exploring the challenges in modern Computer Vision and Multimodal Learning algorithms and model development. The project will include a hands-on implementation of various techniques to identify and solve problems, and to evaluate results in comparison to public benchmarks. It will further provide an understanding of the characteristics of models and benchmarks such as generalization and robustness. The project should provide insights on the development of novel Multimodal Learning technology in response to upcoming challenges.</span></p> <p class="MsoNormal">Teilnahmevoraussetzungen: ML-4103</p> <p class="MsoNormal"><strong>Intro-Veranstaltung: 14.04.2025 , 9:00 - 10:00, Mvl1 A301 Ebene 3 Stockwerk 1</strong></p> <p class="MsoNormal">To sign up for the lab, please join the intro meeting. I''ll give a tour through the open topics and a rough outline of the timeline and expectations. You will then have one week to decide if this would be for you and on which topic you want to work. </p> <p class="MsoNormal">If you can not make it to the intro meeting, please send an email to h.kuehne@uni-tuebingen.de .</p></div>', '[{"display_name": "Hildegard Kühne", "profile_url": "https://moodle.zdv.uni-tuebingen.de/user/profile.php?id=14895", "moodle_user_id": "14895"}]', '[]', '["SS26"]', 1, 0, 0, NULL, NULL, '{"coursebox_classes": ["coursebox", "clearfix", "odd"], "data_type": "1", "course_page_url": "https://moodle.zdv.uni-tuebingen.de/enrol/index.php?id=1658", "enrolment_labels": ["Selbsteinschreibung (Studierende*r)"]}');
INSERT INTO "moodle_courses" ("id", "run_id", "moodle_course_id", "category_id", "title", "normalized_title", "course_url", "enrol_url", "summary_text", "summary_html", "teachers_json", "detected_codes_json", "detected_terms_json", "self_enrol_available", "guest_access", "limit_mentioned", "limit_text", "participant_limit_value", "raw_json") VALUES (33, 1, '1659', '235', 'Seminar - Advances in Multimodal Learning SS26', 'seminar - advances in multimodal learning ss26', 'https://moodle.zdv.uni-tuebingen.de/course/view.php?id=1659', 'https://moodle.zdv.uni-tuebingen.de/enrol/index.php?id=1659', 'General Information This seminar will cover most recent advancements and publications in multimodal learning, which is the integration of multiple data sources or multiple modalities for more complex machine learning applications. This can include reviews of emerging techniques, including unsupervised approaches, deep learning, transfer learning, and reinforcement learning to combine multiple modalities such as images, audio, video, joint feature learning, and natural language processing. It can further cover techniques for data fusion and the role they play in successful applications of multimodal learning. Students will have an opportunity to evaluate and experiment with public code if available. The goal is to develop a better understanding of the possibilities and challenges of multimodal learning. Intro-Veranstaltung: 14.04.2025 , 9:00 - 10:00, Mvl1 A301 Ebene 3 Stockwerk 1 To sign up for the seminar, please join the intro meeting. I''ll give a tour through the open topics and a rough outline of the timeline and expectations. You will then have one week to decide if this would be for you and on which topic you want to work. If you can not make it to the intro meeting, please send an email to h.kuehne@uni-tuebingen.de .', '<div class="no-overflow"><p class="MsoNormal"><strong><span lang="EN-US">General Information</span></strong></p> <p class="MsoNormal">This seminar will cover most recent advancements and publications in multimodal learning, which is the integration of multiple data sources or multiple modalities for more complex machine learning applications. This can include reviews of emerging techniques, including unsupervised approaches, deep learning, transfer learning, and reinforcement learning to combine multiple modalities such as images, audio, video, joint feature learning, and natural language processing. It can further cover techniques for data fusion and the role they play in successful applications of multimodal learning. Students will have an opportunity to evaluate and experiment with public code if available. The goal is to develop a better understanding of the possibilities and challenges of multimodal learning.</p> <p class="MsoNormal"><strong>Intro-Veranstaltung: 14.04.2025 , 9:00 - 10:00, Mvl1 A301 Ebene 3 Stockwerk 1</strong></p> <p class="MsoNormal">To sign up for the seminar, please join the intro meeting. I''ll give a tour through the open topics and a rough outline of the timeline and expectations. You will then have one week to decide if this would be for you and on which topic you want to work. </p> <p class="MsoNormal">If you can not make it to the intro meeting, please send an email to h.kuehne@uni-tuebingen.de .</p></div>', '[{"display_name": "Hildegard Kühne", "profile_url": "https://moodle.zdv.uni-tuebingen.de/user/profile.php?id=14895", "moodle_user_id": "14895"}]', '[]', '["SS26"]', 1, 0, 1, 'Students will have an opportunity to evaluate and experiment with public code if available.', NULL, '{"coursebox_classes": ["coursebox", "clearfix", "even"], "data_type": "1", "course_page_url": "https://moodle.zdv.uni-tuebingen.de/enrol/index.php?id=1659", "enrolment_labels": ["Selbsteinschreibung (Studierende*r)"]}');
INSERT INTO "moodle_courses" ("id", "run_id", "moodle_course_id", "category_id", "title", "normalized_title", "course_url", "enrol_url", "summary_text", "summary_html", "teachers_json", "detected_codes_json", "detected_terms_json", "self_enrol_available", "guest_access", "limit_mentioned", "limit_text", "participant_limit_value", "raw_json") VALUES (34, 1, '1683', '235', 'Proseminar: Topics in Deep Neural Networks SS2026', 'proseminar: topics in deep neural networks ss2026', 'https://moodle.zdv.uni-tuebingen.de/course/view.php?id=1683', 'https://moodle.zdv.uni-tuebingen.de/enrol/index.php?id=1683', 'Deep learning is a subfield of machine learning that has achieved significant state-of-the-art results in many areas of artificial intelligence, including computer vision and robotics, and has been advancing very quickly in recent years. This seminar aims to cover introductory topics in the field of deep learning. A collection of papers from selected journals and conferences is provided for the students to choose from. In each meeting, two topics are presented by the students. Students are graded based on: a) their presentation, b) a short report that they write on the subject, and c) their participation in post-presentation discussions. So, attendance is required to pass the course.', '<div class="no-overflow"><p>Deep learning is a subfield of machine learning that has achieved significant state-of-the-art results in many areas of artificial intelligence, including computer vision and robotics, and has been advancing very quickly in recent years. This seminar aims to cover introductory topics in the field of deep learning. A collection of papers from selected journals and conferences is provided for the students to choose from. In each meeting, two topics are presented by the students. <br/>Students are graded based on: a) their presentation, b) a short report that they write on the subject, and c) their participation in post-presentation discussions. So, attendance is required to pass the course. </p></div>', '[{"display_name": "David Joseph", "profile_url": "https://moodle.zdv.uni-tuebingen.de/user/profile.php?id=28352", "moodle_user_id": "28352"}, {"display_name": "Peizheng Li", "profile_url": "https://moodle.zdv.uni-tuebingen.de/user/profile.php?id=51706", "moodle_user_id": "51706"}]', '[]', '["SS2026"]', 1, 0, 1, 'A collection of papers from selected journals and conferences is provided for the students to choose from.', NULL, '{"coursebox_classes": ["coursebox", "clearfix", "odd", "first"], "data_type": "1", "course_page_url": "https://moodle.zdv.uni-tuebingen.de/enrol/index.php?id=1683", "enrolment_labels": ["Selbsteinschreibung (Studierende*r)"]}');
